#include "room_rules_internal.hpp"
namespace wot::room {
std::vector<Rules::ActorKey> Rules::directSpotters(const ActorKey&target)const{using namespace rule;std::vector<ActorKey>out;const auto*victim=roundActor(target);if(!victim)return out;for(const auto*observers:{&state_.player_spotted,&state_.bot_spotted})for(const auto&[id,seen]:*observers){const ActorKey reporter{observers==&state_.player_spotted?"player":"bot",id};const auto*actor=roundActor(reporter);if(actor&&intField(*actor,"team")!=intField(*victim,"team")&&seen.count(target))out.push_back(reporter);}return out;}
std::vector<Rules::ActorKey> Rules::radioAssisters(const ActorKey&attacker,const ActorKey&target)const{using namespace rule;std::vector<ActorKey>out;const auto*source=roundActor(attacker),*victim=roundActor(target);if(!source||!victim||intField(*source,"team")==intField(*victim,"team"))return out;const auto&own=attacker.first=="player"?state_.player_spotted:state_.bot_spotted;const auto direct=own.find(attacker.second);if(direct!=own.end()&&direct->second.count(target))return out;for(const auto&r:rows(source->get("radio_assist_sources").get(actorString(target)))){const ActorKey reporter{field(r,"kind"),intField(r,"id")};const auto*helper=state_.actor(reporter.first,reporter.second);if(!helper||intField(*helper,"team")!=intField(*source,"team")||!helper->get("connected").truth(true)||r.get("deadline").numeric()<=state_.monotonic_seconds||(reporter==attacker&&!alive(*helper)))continue;out.push_back(reporter);}std::sort(out.begin(),out.end(),[](const auto&a,const auto&b){return std::make_pair(a.first=="player"?0:1,a.second)<std::make_pair(b.first=="player"?0:1,b.second);});out.erase(std::unique(out.begin(),out.end()),out.end());if(std::find(out.begin(),out.end(),attacker)!=out.end())out.clear();return out;}
bool Rules::invisibleFor(const ActorKey&key)const{using namespace rule;const auto*actor=roundActor(key);if(!actor)return true;if(!directSpotters(key).empty())return false;const auto enemy=3-intField(*actor,"team");const auto team=team_lit_deadlines_.find(static_cast<int>(enemy));if(team!=team_lit_deadlines_.end()){const auto lease=team->second.find(key);if(lease!=team->second.end()&&lease->second>state_.monotonic_seconds)return false;}return true;}
}
